        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            sign = (-1) ** j
            det += sign * matrix[0][j] * log_det(submatrix)
        return det

    def tensor_product(matrices):
        if len(matrices) == 1:
            return matrices[0]
        result = matrices[0]
        for i in range(1, len(matrices)):
            new_result = []
